using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.Wpf;
namespace BrowserManager {
 public static class EmbeddedPolicy {
  public static string DataRoot(string home){return Path.Combine(Path.GetFullPath(home),"data","browser","webview2");}
  public static string Profile(string id){if(!Browser.ValidId(id))throw new InvalidOperationException("账号标识无效，未打开内置浏览器。");return "account-"+id;}
  static bool Parse(string value,out Uri uri){uri=null;return value!=null&&value.Length<32767&&!value.Any(c=>char.IsControl(c)||c=='"')&&Uri.TryCreate(value,UriKind.Absolute,out uri);}
  public static bool Web(string value){if(value=="about:blank")return true;Uri u=null;if(!Parse(value,out u)||u.UserInfo.Length!=0)return false;if(u.Scheme=="http")return u.Host=="127.0.0.1"||u.Host=="localhost"||u.Host=="[::1]";if(u.Scheme!="https"||!u.IsDefaultPort)return false;return u.Host=="account.battlenet.com.cn"||new[]{"163.com","126.com","126.net","netease.com"}.Any(host=>u.Host==host||u.Host.EndsWith("."+host,StringComparison.OrdinalIgnoreCase));}
  public static bool External(string value,string origin){Uri target=null,from=null;if(!Parse(value,out target)||!Parse(origin,out from)||from.Scheme!="https"||!from.IsDefaultPort||from.UserInfo.Length!=0)return false;return (from.Host=="account.battlenet.com.cn"||from.Host=="oauth.g.mkey.163.com")&&(target.Scheme=="battlenet"||target.Scheme=="blizzard");}
  public static string Site(string value){Uri u=null;return Parse(value,out u)&&u.Scheme=="https"?u.Host: value=="about:blank"?"等待战网的新登录请求":"当前页面";}
  public static CoreWebView2EnvironmentOptions Options(){return new CoreWebView2EnvironmentOptions{AllowSingleSignOnUsingOSPrimaryAccount=false,AreBrowserExtensionsEnabled=false};}
  public static string WaitingHtml(string label){return "<!doctype html><meta charset=utf-8><style>body{font:16px 'Microsoft YaHei UI';background:#f5f8ff;color:#233658;margin:60px}h1{font-size:28px}p{line-height:1.9}</style><h1>内置登录窗口已就绪</h1><p>账号："+System.Net.WebUtility.HtmlEncode(label)+"</p><p>请回到官方战网，手动点击“登录或注册”。<br>新的登录请求会在这个窗口打开。</p>";}
 }
 public class EmbeddedWindow:Window {
  readonly CoreWebView2Environment environment;readonly string id;readonly WebView2 view=new WebView2();readonly TextBlock site=Ui.Text("正在准备内置浏览器…",12),status=Ui.Text("首次使用此账号时，请手动登录。",12);readonly List<EmbeddedWindow> popups=new List<EmbeddedWindow>();readonly bool fixture;readonly Action<string> notice;ulong lastNavigation,blockedNavigation;
  Task ready;bool clientRequest;public bool ClosedAlready{get;private set;}public bool IsReady{get{return view.CoreWebView2!=null&&!ClosedAlready;}}public Task Ready{get{return ready??Task.FromResult(0);}}public CoreWebView2 Core{get{return view.CoreWebView2;}}internal EmbeddedWindow LatestPopup{get{return popups.LastOrDefault();}}internal string DiagnosticStatus{get{return status.Text;}}
  public EmbeddedWindow(CoreWebView2Environment env,string accountId,string name,Window parent,bool test,Action<string> report=null){environment=env;id=accountId;fixture=test;notice=report;Title="国服登录 · "+name;Width=Math.Min(1050,SystemParameters.WorkArea.Width*0.92);Height=Math.Min(800,SystemParameters.WorkArea.Height*0.90);MinWidth=Math.Min(740,Width);MinHeight=Math.Min(600,Height);FontFamily=new FontFamily("Microsoft YaHei UI");Background=Ui.Brush("#F4F6FB");WindowStartupLocation=parent==null?WindowStartupLocation.CenterScreen:WindowStartupLocation.CenterOwner;if(parent!=null)Owner=parent;
   var root=new DockPanel{Background=Background};Content=root;var header=new StackPanel{Margin=new Thickness(20,14,20,12)};DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);header.Children.Add(Ui.Text(name+" · 内置登录窗口",22));header.Children.Add(Ui.Text("账号资料独立保存 · Windows 微软账号自动登录已关闭",12));header.Children.Add(site);
   var bar=new StackPanel{Orientation=Orientation.Horizontal};header.Children.Add(bar);bar.Children.Add(Ui.Button("返回",delegate{if(IsReady&&Core.CanGoBack&&!clientRequest)Core.GoBack();else if(clientRequest)status.Text="这是战网的新登录请求；需要重试时，请回到战网重新发起。";},false));bar.Children.Add(Ui.Button("重新加载",delegate{if(IsReady&&!clientRequest)Core.Reload();else if(clientRequest)status.Text="请从战网重新发起请求，避免使用超时的登录地址。";},false));bar.Children.Add(Ui.Button("关闭窗口",delegate{Close();},false));
   var bottom=new Border{Child=status,Padding=new Thickness(14),Background=Ui.Brush("#EAF0FF")};DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);root.Children.Add(view);
   Closed+=delegate{ClosedAlready=true;foreach(var popup in popups.ToArray())if(!popup.ClosedAlready)popup.Close();view.Dispose();if(notice!=null)notice(clientRequest?"内置登录窗口已关闭，请以官方战网客户端显示的实际账号为准。":"内置登录窗口已关闭，此账号的浏览器资料仍保留，可重新打开。");};
  }
  public Task Initialize(){if(ready==null)ready=InitializeCore();return ready;}
  async Task InitializeCore(){var controller=environment.CreateCoreWebView2ControllerOptions();controller.ProfileName=EmbeddedPolicy.Profile(id);controller.IsInPrivateModeEnabled=false;await view.EnsureCoreWebView2Async(environment,controller);if(ClosedAlready)throw new OperationCanceledException();var settings=Core.Settings;settings.AreHostObjectsAllowed=false;settings.IsWebMessageEnabled=false;settings.IsPasswordAutosaveEnabled=false;settings.IsGeneralAutofillEnabled=false;settings.AreDevToolsEnabled=fixture;settings.IsStatusBarEnabled=false;
   Core.SourceChanged+=delegate{if(IsReady)site.Text=EmbeddedPolicy.Site(Core.Source);};
   Core.NavigationStarting+=delegate(object sender,CoreWebView2NavigationStartingEventArgs e){lastNavigation=e.NavigationId;if(fixture)return;if(!EmbeddedPolicy.Web(e.Uri)&&!EmbeddedPolicy.External(e.Uri,Core.Source)){e.Cancel=true;blockedNavigation=e.NavigationId;status.Text="页面请求打开其他站点（"+EmbeddedPolicy.Site(e.Uri)+"），已停止。请只反馈这个提示。";}else status.Text=clientRequest?"请手动完成网页登录、必要确认或将军令；完成后核对官方战网账号。":"请手动登录这个账号；网页登录状态会独立保留。";};
   Core.NavigationCompleted+=delegate(object sender,CoreWebView2NavigationCompletedEventArgs e){if(ClosedAlready||e.NavigationId!=lastNavigation||e.NavigationId==blockedNavigation)return;if(!e.IsSuccess)status.Text="网页未能打开（"+e.WebErrorStatus+"；HTTP "+e.HttpStatusCode+"）。新登录请求请从官方战网重新发起。";else if(e.HttpStatusCode==204||e.HttpStatusCode==205)status.Text="网页返回空内容（HTTP "+e.HttpStatusCode+"）。请核对官方战网是否进入账号；这不是登录成功的自动判定。";};
   Core.LaunchingExternalUriScheme+=delegate(object sender,CoreWebView2LaunchingExternalUriSchemeEventArgs e){string origin=string.IsNullOrEmpty(e.InitiatingOrigin)&&clientRequest?Core.Source:e.InitiatingOrigin;e.Cancel=!EmbeddedPolicy.External(e.Uri,origin);status.Text=e.Cancel?"此页面请求打开未识别的外部应用，已停止。":"网页请求回到官方战网；如出现打开应用确认，请手动确认。";};
   Core.DownloadStarting+=delegate(object sender,CoreWebView2DownloadStartingEventArgs e){e.Cancel=true;status.Text="登录窗口不下载文件。";};
   Core.WindowCloseRequested+=delegate{if(ClosedAlready)return;string message=clientRequest?"网页登录页面已请求关闭，请核对官方战网是否进入你选择的账号。":"网页已请求关闭，此账号的内置浏览器资料仍保留，可重新打开窗口。";status.Text=message;if(notice!=null)notice(message);Dispatcher.BeginInvoke(new Action(delegate{if(!ClosedAlready)Close();}),System.Windows.Threading.DispatcherPriority.Background);};
   Core.NewWindowRequested+=Popup;site.Text="内置浏览器已就绪";
  }
  async void Popup(object sender,CoreWebView2NewWindowRequestedEventArgs e){e.Handled=true;if(!EmbeddedPolicy.Web(e.Uri)){status.Text="弹出页面不属于国服登录流程，已停止打开。";return;}var deferral=e.GetDeferral();try{var popup=new EmbeddedWindow(environment,id,"同账号验证页面",this,fixture,notice);if(fixture){popup.ShowInTaskbar=false;popup.ShowActivated=false;popup.WindowStartupLocation=WindowStartupLocation.Manual;popup.Left=-32000;popup.Top=-32000;}popup.clientRequest=clientRequest;popups.Add(popup);popup.Show();await popup.Initialize();e.NewWindow=popup.Core;}catch{status.Text="验证页面未能打开，请从官方战网重新发起登录。";}finally{deferral.Complete();}}
  public void Wait(){if(IsReady){clientRequest=false;Core.NavigateToString(EmbeddedPolicy.WaitingHtml(Title));}}
  public void Navigate(string url,bool fromClient){if(!IsReady)throw new InvalidOperationException("内置浏览器尚未就绪。");clientRequest=fromClient;Core.Navigate(url);}
 }
}
